export const Cells = {
  parameters: { docs: { source: { type: "code" } } },
  render: () => {
    const onClick = (e: any) => e.preventDefault();
    // CellContext type is available when passing to cell
    const LinkCell = (props: DataTableCellContext<ExampleRowData>) => (
      <Link href="#" onClick={onClick}>
        {props.getValue()}
      </Link>
    );
    // HeaderContext type is available when passing to header
    const CreationHeader = (props: DataTableHeaderContext<ExampleRowData>) => (
      <Inline spacing="1-x">
        <span>{props.column.columnDef.meta as string}</span>
        <IconButton
          variant="ghost"
          size="xsmall"
          onClick={(e) => e.stopPropagation()} // prevent sort on click
        >
          <Close />
        </IconButton>
      </Inline>
    );
    const ChipInputCell = (props: DataTableCellContext<ExampleRowData>) => {
      let value = props.getValue();
      const [tag, setTag] = React.useState(value);
      const [submit, setSubmit] = React.useState(false);
      return value || submit ? (
        <Chip label={value || tag} />
      ) : (
        <div style={{ padding: "2px 0" }}>
          <Input
            size="small"
            value={tag}
            onChange={(event) => setTag(event.target.value)}
            onKeyDown={(event) => event.keyCode === 13 && setSubmit(true)}
          />
        </div>
      );
    };
    const MenuCell = () => {
      return (
        <Menu>
          <MenuButton size="small" variant="ghost" component={IconButton}>
            <MoreHoriz />
          </MenuButton>
          <MenuList>
            <MenuItem onClick={onClick} icon={<Visibility />}>
              View
            </MenuItem>
            <MenuItem onClick={onClick} icon={<Delete />}>
              Delete
            </MenuItem>
          </MenuList>
        </Menu>
      );
    };

    const customCellsColumns = React.useMemo(() => {
      const columnHelper = createColumnHelper<ExampleRowData>();
      return [
        columnHelper.accessor((row) => new Date(row.creation), {
          id: "creation",
          meta: "Creation",
          cell: (info) => info.getValue().toLocaleDateString(),
          header: CreationHeader,
          sortingFn: "datetime",
        }),
        columnHelper.accessor("city", {
          cell: (info) => <LinkCell {...info} />,
          header: "City",
        }),
        columnHelper.accessor("type", {
          cell: (info) => info.getValue(),
          header: "Type",
          size: 180,
        }),
        columnHelper.accessor("fir", {
          cell: (info) => <ChipInputCell {...info} />,
          header: "FIR",
          disableSortBy: true,
        }),
        columnHelper.display({
          id: "menu",
          cell: MenuCell,
          size: 70,
          disableSortBy: true,
        }),
      ];
    }, []);
    const data = React.useMemo(() => mockData(8), []);

    return <DataTable columns={customCellsColumns} data={data} />;
  },
};

