export const Expandable: Story = {
  parameters: { docs: { source: { type: "code" } } },
  render: () => {
    // First row with nested data and second row without long description
    const data = React.useMemo(() => {
      const result = mockData(4);
      result[0].nestedData = mockNestedData(2);
      result[1].longDesc = "";
      return result;
    }, []);
    // predefined expanded rows
    const [expandedRows, setExpandedRows] =
      React.useState<DataTableExpandedState>({ "0": true, "2": true });
    // example component used with `renderExpanded` option
    const ExpandedRow = ({ rowData }: { rowData: ExampleRowData }) => {
      return (
        <Flex
          className="datatable-expandedrow-example"
          alignItems="start"
          justify="space-between"
        >
          <Stack spacing="half-x">
            <label>
              <strong>Long description</strong>
            </label>
            <div>{rowData.longDesc}</div>
            {rowData.nestedData && (
              <>
                <label>
                  <strong>Optional nested data</strong>
                </label>
                <pre>{JSON.stringify(rowData.nestedData)}</pre>
              </>
            )}
          </Stack>
          <Stack align="end">
            <Button variant="ghost" size="small">
              <Download />
              Download
            </Button>
            <Button variant="ghost" size="small">
              <Delete />
              Delete
            </Button>
          </Stack>
        </Flex>
      );
    };
    const expandableOptions: DataTableExpandableOptions<ExampleRowData> = {
      expandedRows,
      height: 82,
      getRowHeight: (row: DataTableRow<ExampleRowData>) =>
        row.original.nestedData && row.original.nestedData.length > 0
          ? 124
          : 82,
      isRowExpandable: (row: DataTableRow<ExampleRowData>) => {
        return !!(row.original.longDesc && row.original.longDesc.length > 0);
      },
      onChange: (rows: DataTableExpandedState) => {
        setExpandedRows(rows);
      },
      renderExpanded: (row: DataTableRow<ExampleRowData>) => {
        // see https://tanstack.com/table/v8/docs/api/core/row#original
        // - row.original : original row object from data
        // - row.subRows : available if subRows are passed to data
        // - row.values : map of the row resolved values by columnId
        return <ExpandedRow rowData={row.original} />;
      },
    };
    return (
      <DataTable
        allowDividers
        columns={columns}
        data={data}
        expandable
        expandableOptions={expandableOptions}
      />
    );
  },
};

