export const Persistence: Story = {
  parameters: { docs: { source: { type: "code" } } },
  render: () => {
    const data: ExampleRowData[] = React.useMemo(() => mockData(4), []);
    // "use-local-storage-state" setup for localStorage persistence
    const [myTableState, setMyTableState] = useLocalStorageState<any>(
      "my-persisted-tabls",
      {
        defaultValue: {},
      }
    );
    /* On startup we merge the columns configuration and sorting with persisted state.
     * This process is known as rehydratation. */
    const rehydratedColumns = React.useMemo(() => {
      if (!myTableState.columns) return columns;
      return myTableState.columns.map(({ id, size }: any) => {
        const column = columns.find(
          (c: any) => c.id === id || c.accessorKey === id
        );
        return {
          ...column,
          size,
        };
      });
    }, []);
    const rehydratedSortBy = React.useMemo(() => {
      if (!myTableState.sortBy) return [];
      return myTableState.sortBy;
    }, []);
    return (
      <DataTable
        columns={rehydratedColumns}
        data={data}
        allowResize
        sortBy={rehydratedSortBy}
        onStateUpdate={(state: DataTableState<ExampleRowData>) =>
          setMyTableState(state)
        }
      />
    );
  },
};

export const Controlled: Story = {
  parameters: { docs: { source: { type: "code" } } },
  render: () => {
    const mockServerData = React.useMemo(() => mockData(2000), []);
    /* DataTable props managed externally : data, loading, pageCount, rowCount */
    const [data, setData] = React.useState(mockServerData.slice(0, 10));
    const [loading, setLoading] = React.useState(false);
    const [pageCount, setPageCount] = React.useState(200);
    const [rowCount, setRowCount] = React.useState(2000);
    /* onQueryUpdate will get called when the table needs new data.
     * For this example, we'll just fake a server request each time. */
    const fetchIdRef = React.useRef(0);
    const onQueryUpdate = React.useCallback(
      (queryParams: any) => {
        /* setting the DataTable.loading prop to true has two effects
         *   - show a Spinner component
         *   - deactivate DataTable auto reset of page/sort/etc. */
        setLoading(true);
        /* fake server data fetching */
        const fetchId = ++fetchIdRef.current;
        setTimeout(() => {
          if (fetchId !== fetchIdRef.current) return;
          const queryResult = mockQuery(mockServerData, queryParams);
          setData(queryResult.data);
          setRowCount(queryResult.rowCount);
          setPageCount(queryResult.pageCount);
          setLoading(false);
        }, 500);
      },
      [mockServerData]
    );
    return (
      <DataTable
        columns={columns}
        data={data}
        loading={loading}
        onQueryUpdate={onQueryUpdate}
        pageCount={pageCount}
        rowCount={rowCount}
      />
    );
  },
};

export const ControlledPagination: Story = {
  parameters: { docs: { source: { type: "code" } } },
  render: () => {
    const mockServerData = React.useMemo(() => mockData(2000), []);
    /* DataTable props managed externally : data, loading, pageCount, rowCount */
    const [data, setData] = React.useState(mockServerData.slice(0, 10));
    const [loading, setLoading] = React.useState(false);
    const [pageCount, setPageCount] = React.useState(200);
    const [rowCount, setRowCount] = React.useState(2000);

    // Add fetchIdRef declaration
    const fetchIdRef = React.useRef(0);

    /* Controlled datatable queries */
    const [pageIndex, setPageIndex] = React.useState(0);
    const [pageSize, setPageSize] = React.useState(10);
    const [sortBy, setSortBy] = React.useState([]);
    const [filter, setFilter] = React.useState("");

    // Convert 1-based page number to 0-based index and include filter on page change
    const onPageChange = React.useCallback(
      (evt: any, page: number) => {
        setPageIndex(page - 1);
        onQueryUpdate(
          {
            pageIndex: page - 1,
            pageSize,
            sortBy,
          },
          filter ? { city: filter } : undefined
        );
      },
      [pageSize, sortBy, filter]
    );

    const onCityFilterChange = React.useCallback(
      (value: string) => {
        setFilter(value);
        setPageIndex(0); // Reset to first page on filter change
        onQueryUpdate(
          {
            pageIndex: 0,
            pageSize,
            sortBy,
          },
          { city: value }
        );
      },
      [pageSize, sortBy]
    );
    /* onQueryUpdate will get called when the table needs new data or a page index has changed.
     * For this example, we'll just fake a server request each time. */
    const onQueryUpdate = React.useCallback(
      (queryParams: any, filters?: any) => {
        /* setting the DataTable.loading prop to true has two effects
         *   - show a Spinner component
         *   - deactivate DataTable auto reset of page/sort/etc. */
        setLoading(true);
        /* save query params in local state to trigger queries on filtering */
        setPageSize(queryParams.pageSize);
        setSortBy(queryParams.sortBy);
        /* fake server data fetching */
        const fetchId = ++fetchIdRef.current;
        setTimeout(() => {
          if (fetchId !== fetchIdRef.current) return;

          const queryResult = mockQuery(
            mockServerData,
            { ...queryParams, pageIndex },
            filters || (filter ? { city: filter } : undefined) // Use stored filter
          );

          setData(queryResult.data);
          setRowCount(queryResult.rowCount);
          setPageCount(queryResult.pageCount);
          setLoading(false);
        }, 500);
      },
      [mockServerData, pageIndex, filter]
    );

    return (
      <>
        <div className="p-1 w-208">
          <ComboBox
            placeholder="Filter by city"
            value={filter}
            options={[
              "BOM-ATL",
              "CCU-ATL",
              "CDG-JFK",
              "CDG-TLS",
              "MAD-LHR",
              "SCL-MEL",
              "TLS-ATL",
              "TSL-SIN",
            ]}
            onChange={onCityFilterChange}
          />
        </div>
        <DataTable
          columns={columns}
          data={data}
          loading={loading}
          onQueryUpdate={onQueryUpdate}
          pageCount={pageCount}
          rowCount={rowCount}
          paginationProps={{
            page: pageIndex + 1, // Convert to 1-based page number
            onPageChange,
          }}
        />
      </>
    );
  },
};

export const Infinite: Story = {
  parameters: { docs: { source: { type: "code" } } },
  render: () => {
    const mockServerData = React.useMemo(() => mockData(2000), []);
    // DataTable props managed externally : data, loading
    const [data, setData] = React.useState(mockServerData.slice(0, 5));
    const [loading, setLoading] = React.useState(false);
    const [sortBy, setSortBy] = React.useState([]);
    // fake server fetching
    const fetchIdRef = React.useRef(0);
    const queryData = React.useCallback((params: any, reset = false) => {
      /* setting the DataTable.loading prop to true has two effects
       *   - show a Spinner component
       *   - deactivate DataTable auto reset of page/sort/etc. */
      setLoading(true);
      const fetchId = ++fetchIdRef.current;
      setTimeout(() => {
        if (fetchId !== fetchIdRef.current) return;
        const queryResult = mockQuery(mockServerData, params);
        if (reset) setData(queryResult.data);
        else setData((d) => d.concat(queryResult.data));
        setLoading(false);
      }, 500);
    }, []);
    // Called when the table state change
    const onQueryUpdate = React.useCallback((params: any) => {
      // we need sorts to be able to load more sorted rows
      setSortBy(params.sortBy);
      // reset the table to 5 rows with new sorts
      queryData({ pageIndex: 0, pageSize: 5, sortBy: params.sortBy }, true);
    }, []);
    const loadMore = () =>
      queryData({ pageIndex: data.length / 5 - 1, pageSize: 5, sortBy });
    return (
      <div>
        <DataTable
          allowVirtualization
          columns={columns}
          data={data}
          disablePagination
          loading={loading}
          onQueryUpdate={onQueryUpdate}
        />
        <br />
        <Button variant="primary" onClick={loadMore}>
          Load More
        </Button>
      </div>
    );
  },
};
